//! Applying validated memory proposals to the store.
//!
//! The contract layer already rejected everything unpalatable; this module is the only
//! place that turns an accepted [`MemoryOp`] into SQL. Two rules live here:
//!
//! * `Add` gets a `memory_ref` generated by Rust (the model never chooses one),
//! * `Update` is scoped to the current `(bot_id, group_id)`, so a ref that somehow
//!   escaped validation still cannot touch another group's row.
//!
//! A retired row (`archived_at` set) is refused by the store with
//! [`BotError::MemoryArchived`]. That refusal is a per-op outcome, not a batch failure:
//! one stale ref must not cost the turn its other writes.
//!
//! `Delete` is deliberately absent: deletion is an operator action on the panel.

use std::sync::Arc;

use crate::agent::contract::{MemoryOp, MemoryOpKind};
use crate::error::{BotError, BotResult};
use crate::store::SqliteStore;

/// Outcome of applying one proposal.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ApplyOutcome {
    /// A new memory row with this ref was created.
    Added(String),
    /// An existing memory row was updated.
    Updated(String),
    /// The ref did not belong to this group (defence in depth).
    RejectedOutOfScope,
    /// The ref points at a retired row. Refused, and never revived.
    RejectedArchived(String),
}

/// Applies memory proposals for one group.
pub struct MemoryApplier {
    store: Arc<SqliteStore>,
    /// Provenance stamped on every row this applier writes.
    origin: &'static str,
}

impl MemoryApplier {
    /// An applier for the per-turn agent contract (`origin = 'agy'`).
    pub fn new(store: Arc<SqliteStore>) -> Self {
        Self {
            store,
            origin: crate::store::origin::AGY,
        }
    }

    /// The same applier with an explicit provenance, kept for tests and for any
    /// future non-agent writer that still goes through the contract shape.
    pub fn with_origin(store: Arc<SqliteStore>, origin: &'static str) -> Self {
        Self { store, origin }
    }

    pub fn origin(&self) -> &'static str {
        self.origin
    }

    /// Apply one op.
    ///
    /// `resolve_subject` maps a group-local `speaker_ref` back to the real member id;
    /// it is the caller's job because it owns the batch's alias table. A `None` subject
    /// means the fact is about the group as a whole.
    ///
    /// `resolve_source` maps a batch-local `message_ref` (`m1`) to the real QQ message
    /// id. The batch is gone once the turn ends, so storing the alias would leave a
    /// dangling pointer nobody can dereference later.
    pub async fn apply(
        &self,
        bot_id: &str,
        group_id: &str,
        op: &MemoryOp,
        resolve_subject: impl Fn(&str) -> Option<String>,
        resolve_source: impl Fn(&str) -> Option<String>,
        now: i64,
    ) -> BotResult<ApplyOutcome> {
        let subject_user_id = op.subject_ref.as_deref().and_then(&resolve_subject);
        let resolved: Vec<String> = op
            .source_refs
            .iter()
            .map(|alias| resolve_source(alias).unwrap_or_else(|| alias.clone()))
            .collect();
        let source_ids = serde_json::to_string(&resolved).unwrap_or_else(|_| "[]".into());

        match op.op {
            MemoryOpKind::Add => {
                let memory_ref = self
                    .store
                    .insert_memory_with_origin(
                        bot_id,
                        group_id,
                        subject_user_id.as_deref(),
                        &op.content,
                        &op.kind,
                        &source_ids,
                        op.confidence,
                        self.origin,
                        now,
                    )
                    .await?;
                Ok(ApplyOutcome::Added(memory_ref))
            }
            MemoryOpKind::Update => {
                let Some(target) = op.memory_ref.as_deref() else {
                    return Ok(ApplyOutcome::RejectedOutOfScope);
                };
                // Confirm the ref belongs to this group before writing.
                match self.store.memory_by_ref(bot_id, group_id, target).await? {
                    None => Ok(ApplyOutcome::RejectedOutOfScope),
                    Some(row) if row.is_archived() => {
                        Ok(ApplyOutcome::RejectedArchived(target.to_string()))
                    }
                    Some(_) => {
                        // An applied agent update endorses the row, so provenance flips
                        // to `agy` even when hy3 originally extracted it.
                        match self
                            .store
                            .update_memory_with_origin(
                                bot_id,
                                group_id,
                                target,
                                &op.content,
                                op.confidence,
                                Some(self.origin),
                                now,
                            )
                            .await
                        {
                            Ok(true) => Ok(ApplyOutcome::Updated(target.to_string())),
                            Ok(false) => Ok(ApplyOutcome::RejectedOutOfScope),
                            // The row was retired between the read and the write.
                            Err(BotError::MemoryArchived(_)) => {
                                Ok(ApplyOutcome::RejectedArchived(target.to_string()))
                            }
                            Err(e) => Err(e),
                        }
                    }
                }
            }
        }
    }

    /// Apply a whole batch of accepted ops, counting the outcomes.
    pub async fn apply_all(
        &self,
        bot_id: &str,
        group_id: &str,
        ops: &[MemoryOp],
        resolve_subject: impl Fn(&str) -> Option<String> + Copy,
        resolve_source: impl Fn(&str) -> Option<String> + Copy,
        now: i64,
    ) -> BotResult<ApplySummary> {
        let mut summary = ApplySummary::default();
        for op in ops {
            match self
                .apply(bot_id, group_id, op, resolve_subject, resolve_source, now)
                .await
            {
                Ok(ApplyOutcome::Added(_)) => summary.added += 1,
                Ok(ApplyOutcome::Updated(_)) => summary.updated += 1,
                Ok(ApplyOutcome::RejectedOutOfScope) => summary.out_of_scope += 1,
                Ok(ApplyOutcome::RejectedArchived(_)) => summary.archived += 1,
                Err(_) => summary.failed += 1,
            }
        }
        Ok(summary)
    }
}

/// Counts of what happened while applying a batch.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct ApplySummary {
    pub added: usize,
    pub updated: usize,
    pub out_of_scope: usize,
    /// Updates refused because the target row is retired.
    pub archived: usize,
    pub failed: usize,
}

impl ApplySummary {
    pub fn total(&self) -> usize {
        self.added + self.updated + self.out_of_scope + self.archived + self.failed
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::agent::contract::MemoryOpKind;
    use crate::memory::retrieval::{DEFAULT_BUDGET, RetrievalInput, build};
    use crate::store::migrations;

    async fn store() -> (tempfile::TempDir, Arc<SqliteStore>) {
        let dir = tempfile::tempdir().expect("临时目录");
        let pool = migrations::open_temp(dir.path()).await.expect("迁移");
        (dir, Arc::new(SqliteStore::new(pool)))
    }

    #[tokio::test]
    async fn source_refs_are_stored_as_real_message_ids() {
        let (_d, store) = store().await;
        store.ensure_group("bot", "100", 1).await.expect("建组");
        let op = MemoryOp {
            op: MemoryOpKind::Add,
            subject_ref: None,
            content: "喜欢咖啡".into(),
            kind: "fact".into(),
            source_refs: vec!["m1".into(), "m2".into()],
            confidence: 0.8,
            memory_ref: None,
        };
        let applier = MemoryApplier::new(Arc::clone(&store));
        let resolve_source = |alias: &str| match alias {
            "m1" => Some("982004594".to_string()),
            "m2" => Some("982004595".to_string()),
            _ => None,
        };
        let out = applier
            .apply("bot", "100", &op, |_| None, resolve_source, 20)
            .await
            .expect("apply");
        let ApplyOutcome::Added(memory_ref) = out else {
            panic!("应该新增");
        };
        let row = store
            .memory_by_ref("bot", "100", &memory_ref)
            .await
            .expect("查询")
            .expect("存在");
        // Aliases are batch-local and die with the batch, so the audit trail has to
        // carry the real QQ message ids instead.
        assert_eq!(row.source_message_ids, r#"["982004594","982004595"]"#);
    }

    #[tokio::test]
    async fn update_finds_the_store_key_that_retrieval_injected() {
        let (_d, store) = store().await;
        store.ensure_group("bot", "100", 1).await.expect("建组");
        let memory_ref = store
            .insert_memory("bot", "100", None, "喜欢咖啡", "fact", "[]", 0.8, 10)
            .await
            .expect("写入");
        assert!(memory_ref.starts_with("mem_"));
        assert_ne!(memory_ref, "mem_1");

        let memories = store.list_memories("bot", "100", 500).await.expect("列出");
        let ctx = build(&RetrievalInput {
            memories: &memories,
            query_text: "咖啡",
            speaker_refs: &[],
            subject_aliases: &[],
            budget: DEFAULT_BUDGET,
        });
        assert_eq!(ctx.entries[0].memory_ref, memory_ref);

        let op = MemoryOp {
            op: MemoryOpKind::Update,
            subject_ref: None,
            content: "改成喝茶".into(),
            kind: "fact".into(),
            source_refs: vec![],
            confidence: 0.9,
            memory_ref: Some(memory_ref.clone()),
        };
        let applier = MemoryApplier::new(Arc::clone(&store));
        let out = applier
            .apply("bot", "100", &op, |_| None, |_| None, 20)
            .await
            .expect("apply");
        assert_eq!(out, ApplyOutcome::Updated(memory_ref.clone()));
        let row = store
            .memory_by_ref("bot", "100", &memory_ref)
            .await
            .expect("查询")
            .expect("存在");
        assert_eq!(row.content, "改成喝茶");
    }

    #[tokio::test]
    async fn an_agent_correction_takes_over_the_rows_origin() {
        let (_d, store) = store().await;
        store.ensure_group("bot", "100", 1).await.expect("建组");
        // hy3 extracted it; the agent then corrects it.
        let memory_ref = store
            .insert_memory_with_origin(
                "bot",
                "100",
                None,
                "喜欢咖啡",
                "fact",
                "[]",
                0.6,
                crate::store::origin::HY3,
                10,
            )
            .await
            .expect("写入");
        let op = MemoryOp {
            op: MemoryOpKind::Update,
            subject_ref: None,
            content: "其实不喝咖啡，只喝红茶".into(),
            kind: "fact".into(),
            source_refs: vec![],
            confidence: 0.9,
            memory_ref: Some(memory_ref.clone()),
        };
        let applier = MemoryApplier::new(Arc::clone(&store));
        let out = applier
            .apply("bot", "100", &op, |_| None, |_| None, 20)
            .await
            .expect("apply");
        assert_eq!(out, ApplyOutcome::Updated(memory_ref.clone()));
        let row = store
            .memory_by_ref("bot", "100", &memory_ref)
            .await
            .expect("查询")
            .expect("存在");
        // The brain endorsed it: provenance follows the last writer, not the first.
        assert_eq!(row.origin, crate::store::origin::AGY);
        assert_eq!(row.content, "其实不喝咖啡，只喝红茶");
        let actor: String = sqlx::query_scalar(
            "SELECT actor_kind FROM audit_events WHERE action = 'memory.update'",
        )
        .fetch_one(&store.pool)
        .await
        .expect("审计");
        assert_eq!(actor, crate::store::origin::AGY);
    }
}
